import React, { useEffect, useState } from "react";
import axios from "axios";

function AdminPanel({
  candidateForm,
  setCandidateForm,
  onSave,
  editId,
  setEditId,
  onDelete,
  candidates,
  theme,
  auth, // ✅ pass this from AdminPage
}) {
  // ================= STATES =================
  const [codes, setCodes] = useState([]);
  const [amount, setAmount] = useState(10);        // For generating codes
  const [generating, setGenerating] = useState(false);

  // ================= FETCH VOTER CODES =================
  const fetchCodes = async () => {
    if (!auth || !auth.token) return;
    try {
      const res = await axios.get("http://localhost:5000/api/admin/codes", {
        headers: {
          Authorization: `Bearer ${auth.token}`,
        },
      });
      setCodes(res.data);
    } catch (error) {
      console.error("Failed to fetch voter codes", error);
    }
  };

  useEffect(() => {
    fetchCodes();
  }, [auth]);

  // ================= GENERATE CODES =================
  const generateCodes = async () => {
    if (!auth || !auth.token) return;
    if (amount <= 0) return alert("Amount must be greater than 0");

    try {
      setGenerating(true);
      await axios.post(
        "http://localhost:5000/api/admin/generate-codes",
        { amount },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );

      alert(`Generated ${amount} new codes!`);
      fetchCodes(); // refresh table
    } catch (err) {
      console.error("Failed to generate codes", err);
      alert("Failed to generate codes");
    } finally {
      setGenerating(false);
    }
  };

  // Cancel editing
  const handleCancelEdit = () => {
    setCandidateForm({
      firstName: "",
      lastName: "",
      candidacy: "",
      partylist: "",
      yearLevel: "",
      block: "",
      description: "",
      image: null,
    });
    setEditId(null);
  };

  // Populate form for editing
  const handleEditClick = (c) => {
    setEditId(c._id);
    setCandidateForm({
      firstName: c.firstName,
      lastName: c.lastName,
      candidacy: c.candidacy,
      partylist: c.partylist || "",
      yearLevel: c.yearLevel || "",
      block: c.block || "",
      description: c.description || "",
      image: null,
    });
  };

  // ================= ADMIN CHECK =================
  const isAdmin = auth?.user?.role?.trim().toLowerCase() === "admin";

  return (
    <div
      style={{
        padding: 20,
        borderRadius: 10,
        backgroundColor: theme.card,
        boxShadow: darkModeShadow(theme),
        display: "flex",
        flexDirection: "column",
        gap: 20,
        marginTop: 20,
      }}
    >
      <h3 style={{ color: theme.text }}>
        {editId ? "✏️ Edit Candidate" : "Add Candidate"}
      </h3>

      {/* ================== FORM ================== */}
      <form
        onSubmit={(e) => {
          e.preventDefault();
          onSave();
        }}
        style={{ display: "flex", flexDirection: "column", gap: 10 }}
      >
        {/* Candidate form inputs remain the same */}
        <input
          type="text"
          placeholder="First Name"
          value={candidateForm.firstName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, firstName: e.target.value })
          }
          style={inputStyle(theme)}
          required
        />

        <input
          type="text"
          placeholder="Last Name"
          value={candidateForm.lastName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, lastName: e.target.value })
          }
          style={inputStyle(theme)}
          required
        />

        {/* Add other inputs: candidacy, year, block, partylist, description, image */}
        {/* ... keep your existing form inputs here ... */}

        <div style={{ display: "flex", gap: 10 }}>
          <button type="submit" style={buttonStyle(theme)}>
            {editId ? "Save Changes" : "Add Candidate"}
          </button>
          {editId && (
            <button
              type="button"
              onClick={handleCancelEdit}
              style={cancelButtonStyle}
            >
              Cancel
            </button>
          )}
        </div>
      </form>

      {/* ================== VOTER CODES ================== */}
      <h3 style={{ color: theme.text }}>Voter Codes</h3>

      {/* ================== GENERATE CODES (ADMIN ONLY) ================== */}
      {isAdmin && (
        <div style={{ display: "flex", gap: 10, marginBottom: 10 }}>
          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(Number(e.target.value))}
            placeholder="Amount"
            style={{ padding: 8, borderRadius: 6, width: 80 }}
          />
          <button onClick={generateCodes} style={buttonStyle(theme)}>
            {generating ? "Generating..." : "Generate Codes"}
          </button>
          <button onClick={fetchCodes} style={buttonStyle(theme)}>
            Refresh
          </button>
        </div>
      )}

      <table
        style={{
          width: "100%",
          borderCollapse: "collapse",
          backgroundColor: "#f9f9f9",
        }}
      >
        <thead>
          <tr>
            <th style={tableStyle}>Code</th>
            <th style={tableStyle}>Status</th>
          </tr>
        </thead>

        <tbody>
          {codes.map((c) => (
            <tr key={c._id}>
              <td style={tableStyle}>{c.code}</td>
              <td style={tableStyle}>{c.used ? "Used" : "Unused"}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// =================== STYLES ===================
const inputStyle = (theme) => ({
  padding: 8,
  borderRadius: 6,
  border: `1px solid ${theme.text}33`,
  width: "100%",
  backgroundColor: theme.background,
  color: theme.text,
});

const buttonStyle = (theme) => ({
  padding: "8px 12px",
  borderRadius: 6,
  border: "none",
  backgroundColor: theme.button,
  color: theme.buttonText,
  cursor: "pointer",
  fontWeight: "bold",
});

const cancelButtonStyle = {
  padding: "8px 12px",
  borderRadius: 6,
  border: "none",
  backgroundColor: "#ef4444",
  color: "#fff",
  cursor: "pointer",
  fontWeight: "bold",
};

const darkModeShadow = (theme) =>
  theme.background === "#1f1f2e"
    ? "0 2px 8px rgba(255,255,255,0.05)"
    : "0 2px 8px rgba(0,0,0,0.2)";

const tableStyle = {
  border: "1px solid #ccc",
  padding: 8,
  textAlign: "center",
};

export default AdminPanel;
